import io
from collections import OrderedDict
from random import randint
from taf.internal.scf.scf import SCF
from taf.internal.scf.managed_object import ManagedObject
from taf.internal.scf.list import List
from taf.internal.scf.item import Item
from taf.internal.scf.p import P
from taf.gnb.oam.ne3s.ws.components.base import FunctionalComponent
from taf.gnb.oam.ne3s.ws.components.CM.v1.resources.templates import templates
from taf.gnb.oam.ne3s.ws.components.CM.v1.resources.notifications.messages import (
    ActiveVersion, ProvisionError, NE3SFeedback, CMNotificationGroup, CurrentPlan)
from taf.gnb.oam.ne3s.ws.components.connection.ne3s_service import NE3SService
from taf.gnb.oam.ne3s.ws.components.connection.exceptions import NE3SRequestFailed
from taf.gnb.oam.ne3s.ws.filter import MessageStream, MessageRule
from taf.gnb.oam.ne3s.ws.components.exceptions import OperationFailed, OperationTimeout, OperationPartiallyFailed
from taf.gnb.oam.ne3s.ws.exceptions import StreamTimeoutError
import logging

log = logging.getLogger("taf.gnb.oam.ne3s.ws.logger")


class CMv1(FunctionalComponent):
    PROVISION_CID = 'cid:provisionContent123'
    DEFAULT_UPLOAD_CONFIGURATION_INTERVAL = 30
    STREAMS = None
    SUPPORTED_NOTIFICATIONS = CMNotificationGroup
    _connection = None

    def __init__(self, connection):
        self._connection = connection
        self.cm_all_notifications = MessageStream(name="CM.all", rule=MessageRule(condition=(ActiveVersion,
                                                                                             CurrentPlan)))
        self.STREAMS = [self.cm_all_notifications]

    def provision(self, provision_content):
        log.info("Starting provision")
        log.debug("Provision content: {}".format(provision_content))

        provision_action = 'provision'
        url = self._connection.create_soap_service_url(NE3SService.BULK)

        provision_soap = templates.get_file_content('provision.xml', 'r')

        random_number = randint(int(10e4), int(10e5))
        operation_id = 'Provision_{}'.format(random_number)

        cid_soap = '0.6c9b1d38dec2901c4b97bea78eaecb87a227def4119ce08f@apache.org'
        cid_provision = '8c9b1d38dec2901c4b97bea78eaecb87a227def4119ce08f@apache.org'

        provision_soap = provision_soap.format(
            manager_registration_key=self._connection.REGISTRATION_KEY,
            session_id=self._connection.session_id,
            operation_id=operation_id,
            provision_content='cid:{}'.format(cid_provision),
            manager_id=self._connection.connection_details.manager_id,
            plan_id=random_number
        )

        log.debug("Provision SOAP: {}".format(provision_soap))

        header_provision = {'Content-ID': '<{}>'.format(cid_provision)}
        header_soap = {'Content-ID': '<{}>'.format(cid_soap)}

        fields = OrderedDict()
        fields[cid_soap] = (cid_soap, provision_soap, 'text/xml', header_soap)
        fields[cid_provision] = (cid_provision, provision_content, 'text/xml',
                                 header_provision)

        provision_response = self._connection.send_multipart_soap_message(
            url, fields, action=provision_action)

        log.info("Provision message sent correctly and accepted")
        log.debug("Provision response content {}".format(provision_response))

        return provision_response

    def request_configuration_upload(self):
        url = self._connection.create_soap_service_url(NE3SService.BULK)
        upload_action = 'upload'
        random_number = randint(int(10e4), int(10e5))

        upload_content = templates.get_file_content('upload.xml', 'r')

        upload_content = upload_content.format(
            manager_registration_key=self._connection.REGISTRATION_KEY,
            session_id=self._connection.session_id,
            manager_id=self._connection.connection_details.manager_id,
            operation_id=random_number
        )

        log.debug("Configuration request upload content {}".format(upload_content))

        fields = OrderedDict()
        fields['fields0'] = ('upload_content.xml', upload_content, 'text/xml')

        upload_response = self._connection.send_multipart_soap_message(url, fields, upload_action)

        log.debug("Configuration upload response: {}".format(upload_response))
        return upload_response

    def get_current_plan(self, timeout=10):
        stream_name = "CM.get_current_plan"

        current_plan_stream = self.add_new_msg_stream(stream_name=stream_name, msg_list=[CurrentPlan])
        try:
            self.request_configuration_upload()
            current_plan_msg = current_plan_stream.get(timeout=timeout)
            return current_plan_msg.current_plan

        except NE3SRequestFailed as e:
            err_msg = "Could not get current plan due to NE3S Request Failure with Error: {}".format(e)
            raise OperationFailed(err_msg)

        except StreamTimeoutError as e:
            err_msg = "Requested current plan was not provided in requested time, Error: {}".format(e)
            raise OperationTimeout(err_msg)

        finally:
            self.remove_msg_stream(stream_name=stream_name)

    def get_active_software_version(self, timeout=10):
        stream_name = "CM.get_active_software_version"

        sw_version_stream = self.add_new_msg_stream(stream_name=stream_name, msg_list=[ActiveVersion])
        try:
            self.request_configuration_upload()
            active_sw_version_msg = sw_version_stream.get(timeout=timeout)
            return active_sw_version_msg.active_sw_release_ver

        except NE3SRequestFailed as e:
            err_msg = "Could not get active software version due to NE3S Request Failure with Error: {}".format(e)
            raise OperationFailed(err_msg)

        except StreamTimeoutError as e:
            err_msg = "Requested active software version was not provided in requested time, Error: {}".format(e)
            raise OperationTimeout(err_msg)

        finally:
            self.remove_msg_stream(stream_name=stream_name)

    def set_managed_object_parameter(self, class_name, dist_name, version_name, param_changes, timeout=720.0):
        scf_data = self.__create_scf_with_param_update(class_name, dist_name, version_name, param_changes)
        self.__set_parameter(scf_data, timeout)

    def __create_scf_with_param_update(self, class_name, dist_name, version_name, param_changes):

        scf = SCF()
        scf.raml.cmData['type'] = 'plan'
        managed_object = ManagedObject().create(klass=class_name, dist_name=dist_name,
                                                version=version_name, operation='update')
        for param_name, param_value in param_changes.items():
            if isinstance(param_value, list):
                scf_list = List().create(name=param_name)
                for element in param_value:
                    if len(param_value) > 0 and isinstance(element, dict):
                        self.__add_params_in_item_to_list(scf_list, element)
                    else:
                        self.__add_params_to_list(scf_list, element)
                managed_object.append(scf_list)
            else:
                par = P().create(name=param_name, value=param_value)
                managed_object.append(par)

        scf.raml.cmData.append(managed_object)
        tree_string = scf.to_string()
        scf_obj = io.BytesIO(tree_string.encode())
        return scf_obj

    def __add_params_in_item_to_list(self, scf_list, element):
        item = Item().create()
        for key, value in element.items():
            par = P().create(name=key, value=value)
            item.append(par)
        scf_list.append(item)
        return scf_list

    def __add_params_to_list(self, scf_list, element):
        par = P().create(value=element)
        scf_list.append(par)
        return scf_list

    def set_parameter_by_scf(self, scf_data, timeout=720.0):
        self.__set_parameter(scf_data, timeout)

    def __set_parameter(self, scf_data, timeout):
        stream_name = 'CM.set_parameter'
        set_param_stream = self.add_new_msg_stream(stream_name=stream_name, msg_list=[NE3SFeedback, ProvisionError])
        try:
            provision_response = self.provision(provision_content=scf_data)
            self.__wait_for_set_param_success(set_param_stream, timeout)

        except NE3SRequestFailed as e:
            self.remove_msg_stream(stream_name)
            err_msg = "Could not send provision message due to NE3S Request Failure with Error: {}".format(e)
            raise OperationFailed(err_msg)

        except StreamTimeoutError as e:
            self.remove_msg_stream(stream_name)
            err_msg = "Set parameter notification was not provided in requested time, Error: {}".format(e)
            raise OperationTimeout(err_msg)
        self.remove_msg_stream(stream_name)
        return provision_response

    def __wait_for_set_param_success(self, stream, timeout):
        notification = stream.get(timeout)

        if self.__is_validation_successful(notification):
            return
        elif self.__is_operation_failure(notification):
            self.remove_msg_stream(stream.name)
            raise OperationFailed(str(notification))
        elif self.__is_operation_partially_failure(notification):
            self.remove_msg_stream(stream.name)
            msg = 'Parameters only partially changed.\n{}'.format(str(notification))
            raise OperationPartiallyFailed(msg)

    def __is_validation_successful(self, notification):
        is_param_change_notification = isinstance(notification, NE3SFeedback)
        return is_param_change_notification and notification.status == 'ok'

    def __is_operation_partially_failure(self, notification):
        is_ne3sfeedback = isinstance(notification, NE3SFeedback)
        return is_ne3sfeedback and notification.status == 'partial'

    def __is_operation_failure(self, notification):
        is_ne3sfeednack_failure = \
            isinstance(notification, NE3SFeedback) and notification.status == 'not_ok'
        is_error = isinstance(notification, ProvisionError)
        return is_ne3sfeednack_failure or is_error
